export const receiveRazorpayWebhook = async (razorpayWebhook: RazorpayWebhook, options?: Parameters<typeof customFetch>[1]): Promise<WebhookResponse> => {

  return customFetch<WebhookResponse>(getReceiveRazorpayWebhookUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(razorpayWebhook)
  }
);}





